using CodeAssist.Core;
using System.Xml.Serialization;
namespace CodeAssist.Core.Tests;
public sealed class DisplaySourceLinkTests {
 [Theory][InlineData("URL")][InlineData("GitHub")][InlineData("FogBugz")][InlineData("Jira")][InlineData("File Viewer")][InlineData("External Tool")]
 public void ProviderPresetsAreValid(string name){SourceLinks.Validate(SourceLinks.Preset(name));}
 [Fact] public void RawUrlProviderRetainsWholeUri(){var result=Assert.Single(SourceLinks.Find("visit https://example.com/issues/22",new[]{SourceLinks.Preset("URL")}));Assert.Equal("https://example.com/issues/22",result.Uri.AbsoluteUri);}
 [Fact] public void FileProviderResolvesCapturedFilenameAndLine(){var target=Path.Combine(Path.GetTempPath(),"source-{id}.cpp");var rule=new SourceLinkRule {Provider=SourceLinkProvider.FileViewer,Pattern=@"file (?<id>\d+):(?<line>\d+)",RegularExpression=true,Target=target};var result=Assert.Single(SourceLinks.Find("// file 12:31",new[]{rule}));Assert.Equal(target.Replace("{id}","12"),result.TargetPath);Assert.Equal(31,result.Line);Assert.Equal(SourceLinkProvider.FileViewer,result.Provider);}
 [Fact] public void ExternalToolCapturesCannotCreateAdditionalArguments(){var rule=new SourceLinkRule {Provider=SourceLinkProvider.ExternalTool,RegularExpression=true,Pattern=@"run \[(?<id>.*)\]",Target=Path.Combine(Path.GetTempPath(),"viewer.exe"),Arguments="--name {id}"};var result=Assert.Single(SourceLinks.Find("run [a\" --other value]",new[]{rule}));Assert.Equal("\"--name\" \"a\\\" --other value\"",result.Arguments);}
 [Fact] public void KeywordAndSuffixControlsAffectMatching(){var rule=new SourceLinkRule {Pattern="old {id}",Keywords="BUG-;TASK-",Suffix="!",Target="https://example.com/{id}"};Assert.Equal(2,SourceLinks.Find("BUG-12! TASK-34! old 99",new[]{rule}).Count);}
 [Fact] public void TextValueKindAcceptsIdentifiers(){var rule=new SourceLinkRule {Pattern="issue {id}",ValueKind="Text",Target="https://example.com/{id}"};Assert.EndsWith("/alpha-beta",Assert.Single(SourceLinks.Find("issue alpha-beta",new[]{rule})).Uri.AbsoluteUri);}
 [Fact] public void UnknownArgumentsAndRelativeToolPathsAreRejected(){Assert.Throws<ArgumentException>(()=>SourceLinks.Validate(new SourceLinkRule {Provider=SourceLinkProvider.ExternalTool,Pattern="#{id}",Target="tool.exe"}));Assert.Throws<ArgumentException>(()=>SourceLinks.Validate(new SourceLinkRule {Provider=SourceLinkProvider.ExternalTool,Pattern="#{id}",Target=Path.Combine(Path.GetTempPath(),"tool.exe"),Arguments="{missing}"}));}
 [Fact] public void ProviderFieldsSurvivePreferenceCopy(){var p=new StartupPreferences {IntegratedMainMenu=false,SourceLinkPluginDirectories="providers",SourceLinkOpenGesture="Alt+click"};var rule=SourceLinks.Preset("External Tool");rule.Scope="User";p.SourceLinkRules.Add(rule);var copy=p.Copy();Assert.Equal(SourceLinkProvider.ExternalTool,copy.SourceLinkRules[0].Provider);Assert.Equal(rule.Arguments,copy.SourceLinkRules[0].Arguments);Assert.False(copy.IntegratedMainMenu);Assert.Equal("Alt+click",copy.SourceLinkOpenGesture);}
 [Fact] public void ProviderManifestImportDoesNotExecuteAnything(){var folder=Path.Combine(Path.GetTempPath(),"CA-providers-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{using(var stream=File.Create(Path.Combine(folder,"providers.xml")))new XmlSerializer(typeof(SourceLinkRuleCatalog)).Serialize(stream,new SourceLinkRuleCatalog {Rules=new(){SourceLinks.Preset("GitHub"),SourceLinks.Preset("External Tool")}});Assert.Equal(2,SourceLinks.ImportDirectory(folder).Count);}finally{Directory.Delete(folder,true);}}
 [Fact] public void ProviderManifestRejectsExternalEntities(){var folder=Path.Combine(Path.GetTempPath(),"CA-providers-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{File.WriteAllText(Path.Combine(folder,"invalid.xml"),"<!DOCTYPE SourceLinks [<!ENTITY x SYSTEM 'file:///no-access'>]><SourceLinks>&x;</SourceLinks>");Assert.ThrowsAny<InvalidOperationException>(()=>SourceLinks.ImportDirectory(folder));}finally{Directory.Delete(folder,true);}}
 [Fact] public void ObjectAndFunctionMacrosExpand(){var text="#define BASE 7\n#define SUM(a,b) ((a)+(b))\n";Assert.Equal("((7)+(f(2,3)))",DisplayQuickInfo.ExpandMacro(text,"SUM(BASE,f(2,3))"));}
 [Fact] public void MacroArgumentsAreSubstitutedSimultaneously(){Assert.Equal("b + a",DisplayQuickInfo.ExpandMacro("#define SUM(a,b) a + b","SUM(b,a)"));}
 [Fact] public void EmptyParameterMacroExpands(){Assert.Equal("42",DisplayQuickInfo.ExpandMacro("#define ANSWER() 42","ANSWER()"));}
 [Fact] public void QuotedMacroNamesAreNotExpanded(){Assert.Equal("\"VALUE\" + 4",DisplayQuickInfo.ExpandMacro("#define VALUE 4", "\"VALUE\" + VALUE"));}
 [Fact] public void MacroUndefAndCyclesAreBounded(){Assert.Equal("A",DisplayQuickInfo.ExpandMacro("#define A 5\n#undef A", "A"));Assert.True(DisplayQuickInfo.ExpandMacro("#define A B\n#define B A","A").Length<=1);}
 [Fact] public void MacroDisplayOptionsControlOriginalAndFormatting(){var source="#define BODY { first(); second(); }\nBODY";var p=new StartupPreferences {EnhancedMacroExpansion=true,KeepOriginalMacroExpansion=true,FormatMacroExpansion=true};var rows=DisplayQuickInfo.MacroPreview(source,source.LastIndexOf("BODY",StringComparison.Ordinal),"BODY",p);Assert.Equal(2,rows.Count);Assert.Contains("\n",rows[1]);p.KeepOriginalMacroExpansion=false;Assert.Single(DisplayQuickInfo.MacroPreview(source,source.LastIndexOf("BODY",StringComparison.Ordinal),"BODY",p));p.EnhancedMacroExpansion=false;Assert.Empty(DisplayQuickInfo.MacroPreview(source,0,"BODY",p));}
 [Fact] public void DoxygenToggleControlsCommentFormatting(){var source="/// @brief Runs a task\n/// @param value Input\nvoid Run(int value);";Assert.Contains("@brief",DisplayQuickInfo.CommentAbove(source,3,false));var formatted=DisplayQuickInfo.CommentAbove(source,3,true);Assert.DoesNotContain("@brief",formatted);Assert.Contains("value — Input",formatted);}
 [Theory][InlineData(true,true,true)][InlineData(true,false,false)][InlineData(false,true,false)][InlineData(false,false,true)]
 public void IntegratedMenuSwitchChoosesExactlyOneLocation(bool preference,bool main,bool visible){Assert.Equal(visible,DisplayQuickInfo.IntegratedMenuVisible(preference,main));}
}
